PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')));
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT NOT NULL, password_hash TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'UTC', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')));
CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower_unique ON users(lower(email));
CREATE TABLE IF NOT EXISTS user_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, chronotype TEXT NOT NULL DEFAULT 'neutral', focus_block_minutes INTEGER NOT NULL DEFAULT 45, break_minutes INTEGER NOT NULL DEFAULT 10 CHECK(break_minutes BETWEEN 0 AND 60), flexibility TEXT NOT NULL DEFAULT 'medium', workload TEXT NOT NULL DEFAULT 'medium', deep_work_period TEXT NOT NULL DEFAULT 'afternoon', activity_start TEXT NOT NULL DEFAULT '09:00:00', activity_end TEXT NOT NULL DEFAULT '18:00:00', version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), CHECK(activity_end > activity_start));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, client_request_id TEXT NOT NULL, title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), description TEXT NOT NULL DEFAULT '', duration_minutes INTEGER NOT NULL CHECK(duration_minutes BETWEEN 1 AND 10080), priority INTEGER NOT NULL DEFAULT 5 CHECK(priority BETWEEN 1 AND 10), status TEXT NOT NULL DEFAULT 'pending', splittable INTEGER NOT NULL DEFAULT 0, preferred_period TEXT NOT NULL DEFAULT 'any', earliest_start TEXT, deadline TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), creation_digest TEXT, deleted_at TEXT, recurrence_id TEXT, occurrence_date TEXT, UNIQUE(user_id,client_request_id), UNIQUE(id,user_id), UNIQUE(user_id,recurrence_id,occurrence_date), FOREIGN KEY(recurrence_id,user_id) REFERENCES recurring_activities(id,user_id), CHECK((recurrence_id IS NULL)=(occurrence_date IS NULL)));
CREATE INDEX IF NOT EXISTS tasks_owner_live_created ON tasks(user_id,created_at DESC,id DESC) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS sessions(token_digest TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, start_at TEXT NOT NULL, end_at TEXT NOT NULL CHECK(end_at > start_at), timezone TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, current_revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), UNIQUE(id,user_id));
CREATE INDEX IF NOT EXISTS schedules_owner_horizon ON schedules(user_id,start_at,end_at);
CREATE TABLE IF NOT EXISTS schedule_versions(schedule_id TEXT NOT NULL, user_id TEXT NOT NULL, revision INTEGER NOT NULL, state TEXT NOT NULL CHECK(json_valid(state) AND length(state) <= 524288), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), PRIMARY KEY(schedule_id,revision), FOREIGN KEY(schedule_id,user_id) REFERENCES schedules(id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS schedule_commands(user_id TEXT NOT NULL, client_request_id TEXT NOT NULL, schedule_id TEXT NOT NULL, request_digest TEXT NOT NULL, applied_version INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), PRIMARY KEY(user_id,client_request_id), FOREIGN KEY(schedule_id,user_id) REFERENCES schedules(id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS schedule_allocations(user_id TEXT NOT NULL, task_id TEXT NOT NULL, schedule_id TEXT NOT NULL, PRIMARY KEY(user_id,task_id), FOREIGN KEY(schedule_id,user_id) REFERENCES schedules(id,user_id) ON DELETE CASCADE, FOREIGN KEY(task_id,user_id) REFERENCES tasks(id,user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS recurring_activities(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, client_request_id TEXT NOT NULL, creation_digest TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', duration_minutes INTEGER NOT NULL CHECK(duration_minutes BETWEEN 1 AND 1440), priority INTEGER NOT NULL DEFAULT 5, splittable INTEGER NOT NULL DEFAULT 0, preferred_period TEXT NOT NULL DEFAULT 'any', frequency TEXT NOT NULL, weekdays TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(weekdays)), start_date TEXT NOT NULL, end_date TEXT, active INTEGER NOT NULL DEFAULT 1, timezone TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), deleted_at TEXT, UNIQUE(user_id,client_request_id), UNIQUE(id,user_id));
CREATE TABLE IF NOT EXISTS fixed_events(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 0 AND 200), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL CHECK(ends_at > starts_at), version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')));
CREATE INDEX IF NOT EXISTS fixed_events_user_time_idx ON fixed_events(user_id,starts_at,ends_at);
INSERT OR IGNORE INTO schema_migrations(version) VALUES(6);
